"""The 63 official U.S. National Parks, plus a real traced US coastline for
the map -- continental US, Alaska, and Hawaii as three insets, the same
convention real US maps use since Alaska and Hawaii are too far away to plot
at true scale/position alongside the lower 48.

The coastline itself is real Census Bureau boundary data (via the public-domain
us-atlas project, https://github.com/topojson/us-atlas), decoded from TopoJSON
to plain SVG path data once and baked in below -- not hand-drawn, and not fetched
at runtime, so this page has no external dependency and no network call.
"""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class Park:
    key: str
    name: str
    states: str
    region: str
    lat: float
    lon: float


