def map_insets() -> dict:
    """The three inset boxes' path data and viewBox dimensions -- for the
    page to draw the <svg> elements themselves."""
    return _MAP_INSETS


def project(lat: float, lon: float) -> tuple[str, float, float] | None:
    """Which inset a park's real coordinates fall in, and its pixel x/y
    within that inset's own SVG viewBox. None for the two territories
    outside all three insets (American Samoa, the Virgin Islands) -- they
    still show in the list, just not pinned on the map."""
    for name, box in _MAP_INSETS.items():
        if box["lon_min"] <= lon <= box["lon_max"] and box["lat_min"] <= lat <= box["lat_max"]:
            x = (lon - box["lon_min"]) / (box["lon_max"] - box["lon_min"]) * box["w"]
            y = (box["lat_max"] - lat) / (box["lat_max"] - box["lat_min"]) * box["h"]
            return name, x, y
    return None
